SELECT r.id, r.thread_id, r.user_id, u.real_name as user_name, u.avatar as user_avatar, r.parent_reply_id, r.content, r.create_time, r.update_time FROM mg_thread_reply r LEFT JOIN sys_user u ON r.user_id = u.id AND u.is_deleted = 0
r.is_deleted = 0
AND r.thread_id = #{threadId}
AND r.user_id = #{userId}
AND r.parent_reply_id = #{parentReplyId}
ORDER BY ${orderByColumn} ${isAsc == 'asc' ? 'ASC' : 'DESC'}
ORDER BY r.create_time ASC
